/* ===== ФОНЫ: картинки + «живая» анимация кодом (покачивание камеры, искры, туман, мерцание, блики) ===== */
const BGI={};['bg_about','menu','arena','bg_mac','bg_ora','bg_bus','bg_shd','bg_inf','bg_slv1','bg_slv2','bg_slv3','bg_coin'].forEach(k=>{if(AS[k]){const im=new Image();im.src=b2u(AS[k],'image/webp');BGI[k]=im}});
/* emb — искры (количество), fog — туман, fl — мерцание огня */
const AMB={menu:{emb:70,fl:.05},arena:{fog:7},bg_mac:{emb:40,fl:.045},bg_ora:{emb:22,fl:.05},bg_bus:{fl:.03,emb:10},bg_shd:{fog:5},bg_inf:{emb:46,fl:.05}};
let curBg=null;function setBg(k){curBg=k}
function cover(c,v,vw,vh,x,y,w,h){if(!vw||!vh)return;const k=Math.max(w/vw,h/vh),dw=vw*k,dh=vh*k;c.drawImage(v,x+(w-dw)/2,y+(h-dh)/2,dw,dh)}
const hs1=n=>{const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
function bgDraw(g,k,x,y,w,h){const im=BGI[k];if(!im||!im.complete||!im.naturalWidth)return;
 const t=performance.now()/1000,a=AMB[k]||{},u=h/360;
 /* медленное «дыхание» камеры */
 const s=1.035+.012*Math.sin(t*.21),ox=Math.sin(t*.13)*.008*w,oy=Math.cos(t*.17)*.006*h;
 cover(g,im,im.naturalWidth,im.naturalHeight,x-(s-1)*w/2+ox,y-(s-1)*h/2+oy,w*s,h*s);
 g.save();g.globalCompositeOperation='lighter';
 if(a.fog){for(let i=0;i<a.fog;i++){const cx=x+w*(((hs1(i)+t*.011*(1+hs1(i+5)))%1.4)-.2),cy=y+h*(.6+.3*hs1(i+2)),r=w*(.18+.12*hs1(i+9));
   const gr=g.createRadialGradient(cx,cy,0,cx,cy,r);gr.addColorStop(0,'rgba(215,222,240,.10)');gr.addColorStop(1,'rgba(215,222,240,0)');g.fillStyle=gr;g.fillRect(cx-r,cy-r,2*r,2*r)}}
 if(a.fl){const n=(Math.sin(t*7.3)+Math.sin(t*11.1+1)+Math.sin(t*3.7+2))/3;g.fillStyle='rgba(255,130,50,'+(a.fl*(.5+.5*n))+')';g.fillRect(x,y,w,h)}
 if(a.emb){for(let i=0;i<a.emb;i++){const sp=.05+.09*hs1(i),ph=(t*sp+hs1(i+7))%1,py=y+h*(1.05-ph*1.15),
   px=x+w*hs1(i+3)+Math.sin(t*(.7+hs1(i))*2+i)*12*u,r=(.8+1.8*hs1(i+11))*u,al=Math.sin(ph*Math.PI)*(.55+.45*Math.sin(t*6+i));
   if(al<=0)continue;g.globalAlpha=al*.35;g.fillStyle='#ff7a2a';g.beginPath();g.arc(px,py,r*2.6,0,7);g.fill();
   g.globalAlpha=al;g.fillStyle=i%3?'#ffb050':'#ffe0a0';g.beginPath();g.arc(px,py,r,0,7);g.fill()}g.globalAlpha=1}
 g.restore()}
