 const h=(id==='shd'?92:id==='man'?205:118)*k,w=h*c.width/c.height,x=e.x+e.f*((b.hw||40)*.55+(id==='shd'?14:24)),y=GY+e.y-(id==='man'?104:id==='shd'?52:(b.fy||60)+6),col=SHC[id]||'#8cc8ff',dark=id==='shd';
