function dRescue(g){
 const p=g.p,kx=p.x>150?p.x-80:p.x+80;g.kill=0;g.dg.zone=null;
 g.resq={t:0,st:0,kx,done:0};g.kry={x:kx,f:kx<DXp()?1:-1,a:'appear',t:0,cd:4}}
function resqUpd(g,dt){
 const r=g.resq,p=g.p,k=g.kry;if(!r||r.done)return;r.t+=dt;
 /* молнии перерисовываются каждые ~60 мс, со вспышками */
 r.lt=(r.lt||0)-dt;r.fl=Math.max(0,(r.fl||0)-dt*4);
 if((r.st===1||(r.st===2&&r.t<2.4))&&r.lt<=0){r.lt=rnd(.045,.08);r.lb=[];
  if(r.st===1){const n=3+Math.floor(Math.random()*3);for(let i=0;i<n;i++)r.lb.push(...lbGen(p.x+rnd(-6,6),GY-14,r.kx+rnd(-25,25),GY-rnd(70,150),rnd(1.6,3.2),2))}
  else{const n=5+Math.floor(Math.random()*4);for(let i=0;i<n;i++){const big=i<2,top=big?-30:rnd(-30,GY*.45);
    r.lb.push(...lbGen(r.kx+rnd(-140,140)*(big?.25:1),top,r.kx+rnd(-30,30)*(big?.4:1.5),big?GY-6:GY-rnd(10,120),big?rnd(3,4.4):rnd(1,2.4),big?3:2))}
   if(Math.random()<.45){r.fl=1;g.sa=Math.max(g.sa||0,3);g.sh=Math.max(g.sh||0,.08)}}}
 if(r.st===0&&r.t>.05){r.st=1;SFX.fx('k_appear',.9);g.wf2=.6}                   /* молнии из ногтей */
 if(r.st===1&&r.t>.75){r.st=2;k.t=0}
 if(r.st===2&&r.t>1.9)say(g,'v_kry2');                                             /* появляется Крыстина */
 if(r.st===2&&r.t>3.6){r.st=3;set(p,'rev',1.1);SFX.chime(2)}                     /* лечение */
 if(r.st===3){p.hp=Math.min(100,p.hp+dt*95)}
 if(r.st===3&&r.t>4.8){r.st=4;p.hp=100;mode(p,'idle');p.at=0;g.aura=1;k.a='cast';k.t=0;k.big=1}
 if(r.st===4&&r.t>7.0){r.done=1;g.saved=1;g.dg.cd=1.5;ban('Закончим это вместе!')}}
function kryUpd(g,dt){
 const k=g.kry;if(!k)return;k.t+=dt;
 if(k.a==='appear'&&g.resq&&g.resq.st<2)k.t=0;
 if(k.a==='appear'&&k.t>17/6){k.a='idle';k.t=0}
 if(k.a==='cast'){if(!k.shot&&k.t>1.45){k.shot=1;SFX.fx('k_cast',.85);
   k.orb={x:k.x+k.f*70,y:GY-95,t:0,big:k.big?1:0,tr:[]};if(k.big){g.sh=.3;g.sa=5}}
  if(k.t>14/8){k.a='idle';k.t=0;k.shot=0;k.big=0}}
 if(k.a==='idle'&&g.saved&&!g.end){k.cd-=dt;if(k.cd<=0){k.cd=rnd(3.8,5);k.a='cast';k.t=0;k.f=k.x<DXp()?1:-1;k.nc=(k.nc||0)+1;if(k.nc===1)say(g,'v_kry1');else if(k.nc===2)say(g,'v_kry3')}}
 if(k.orb){const o=k.orb;o.t+=dt;const T=o.big?.75:.55,q=Math.min(1,o.t/T);o.cx=o.x+(DXp()-o.x)*q;o.cy=o.y+(DHEAD[1]+20-o.y)*q-Math.sin(q*Math.PI)*(o.big?60:40);
  /* шлейф из языков энергии */
  for(let i=0;i<(o.big?5:3);i++)o.tr.push({x:o.cx+rnd(-6,6)*(o.big?2:1),y:o.cy+rnd(-6,6)*(o.big?2:1),vx:rnd(-30,30),vy:rnd(-60,-10),l:0,m:rnd(.25,.5),s:rnd(5,10)*(o.big?1.8:1),c:i%3});
  if(q>=1){if(!g.end){if(o.big){SFX.fx('d_roar',.9);dDamage(g,g.b.hp*.35);fxRed(g,DXp(),DHEAD[1]+20,2);g.sh=.4;g.sa=7;g.wf2=.35}else{dDamage(g,7);fxRed(g,DXp(),DHEAD[1]+20,1)}}
   k.orb=null;k.trail=o.tr}}
 for(const L of [k.orb&&k.orb.tr,k.trail]){if(!L)continue;for(let i=L.length-1;i>=0;i--){const f=L[i];f.l+=dt;if(f.l>=f.m){L.splice(i,1);continue}f.x+=f.vx*dt;f.y+=f.vy*dt;f.s*=1-dt*.8}}}


/* ===== ЭФФЕКТЫ ФИНАЛА ===== */
function fxRed(g,x,y,pw){const n=pw>1?40:18;for(let i=0;i<n;i++){const a=rnd(0,6.283),v=rnd(120,380)*(pw>1?1.3:1);
 g.fx.push({k:'s',t:0,m:rnd(.25,.6),x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,c:['#ff2a3a','#ff7a8a','#ffd0d0','#c0102a'][i%4],w:rnd(1.4,2.6)})}}
/* ветвящиеся молнии: ломаная методом смещения середины + отростки */
function lbGen(x0,y0,x1,y1,w,depth){const segs=[];
 const mid=(a,b,d,n)=>{if(n<=0)return[a,b];const mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2,dx=b[0]-a[0],dy=b[1]-a[1],L=Math.hypot(dx,dy)||1,o=rnd(-1,1)*d;
  const m=[mx-dy/L*o,my+dx/L*o];const A=mid(a,m,d*.55,n-1),B2=mid(m,b,d*.55,n-1);return A.concat(B2.slice(1))};
 const L=Math.hypot(x1-x0,y1-y0),pts=mid([x0,y0],[x1,y1],L*.22,depth>1?5:4);segs.push({p:pts,w});let nb=0;
 if(depth>0)for(let i=2;i<pts.length-3&&nb<(depth>1?4:2);i++)if(Math.random()<.12){nb++;const a=pts[i],an=Math.atan2(y1-y0,x1-x0)+rnd(.4,1.1)*(Math.random()<.5?-1:1),l=L*rnd(.12,.35);
  lbGen(a[0],a[1],a[0]+Math.cos(an)*l,a[1]+Math.sin(an)*l,w*.5,Math.min(depth-1,1)).forEach(s=>segs.push(s))}
 return segs}
function lbDraw(segs,al){cx.save();cx.globalCompositeOperation='lighter';cx.lineCap='round';cx.lineJoin='round';
 const pass=(wk,col,blur)=>{cx.strokeStyle=col;cx.shadowColor='#ff1030';cx.shadowBlur=blur;
  for(const s of segs){cx.lineWidth=Math.max(.6,s.w*wk);cx.beginPath();cx.moveTo(s.p[0][0],s.p[0][1]);for(let i=1;i<s.p.length;i++)cx.lineTo(s.p[i][0],s.p[i][1]);cx.stroke()}};
 pass(8,'rgba(255,20,50,'+(.13*al)+')',0);pass(3.4,'rgba(255,50,80,'+(.5*al)+')',12);pass(1.4,'rgba(255,190,200,'+(.9*al)+')',0);pass(.6,'rgba(255,255,255,'+al+')',0);cx.restore()}
function bolt(x0,y0,x1,y1,w,col){cx.strokeStyle=col;cx.lineWidth=w;cx.beginPath();cx.moveTo(x0,y0);const n=9;
 for(let i=1;i<n;i++){const q=i/n;cx.lineTo(x0+(x1-x0)*q+rnd(-12,12),y0+(y1-y0)*q+rnd(-12,12))}cx.lineTo(x1,y1);cx.stroke()}
/* красная аура героини: несколько оттенков красного */
function auraDraw(p,t,back){
 const x=p.x,y=GY+p.y,pu=.85+.15*Math.sin(t*9);cx.save();cx.globalCompositeOperation='lighter';
 const C=['rgba(255,30,50,','rgba(220,0,35,','rgba(150,0,30,','rgba(255,120,130,','rgba(255,60,90,'];
 if(back){ /* широкое багровое сияние вокруг героини */
  let gr=cx.createRadialGradient(x,y-50,4,x,y-50,115);gr.addColorStop(0,'rgba(255,220,220,'+.75*pu+')');gr.addColorStop(.25,'rgba(255,30,50,'+.6*pu+')');gr.addColorStop(.6,'rgba(170,0,30,'+.35*pu+')');gr.addColorStop(1,'rgba(90,0,15,0)');
  cx.fillStyle=gr;cx.fillRect(x-120,y-170,240,190);
  gr=cx.createRadialGradient(x,y,0,x,y,90);gr.addColorStop(0,'rgba(255,40,60,'+.55*pu+')');gr.addColorStop(1,'rgba(255,0,30,0)');cx.save();cx.translate(x,y);cx.scale(1,.25);cx.fillStyle=gr;cx.beginPath();cx.arc(0,0,90,0,7);cx.fill();cx.restore()}
 for(let i=0;i<(back?18:10);i++){const ph=(t*1.7+i*.29)%1,ox=Math.sin(i*2.3+t*3)*30*(1-ph*.5),oy=-ph*135,r=(back?22:12)*(1-ph*.65);
  const c=C[i%5],gr=cx.createRadialGradient(x+ox,y-6+oy,0,x+ox,y-6+oy,r);gr.addColorStop(0,c+(back?.9:.7)*(1-ph)+')');gr.addColorStop(1,c+'0)');
  cx.fillStyle=gr;cx.beginPath();cx.arc(x+ox,y-6+oy,r,0,7);cx.fill()}
 if(!back)for(let i=0;i<12;i++){const ph=(t*1.1+i*.13)%1;cx.globalAlpha=1-ph;cx.fillStyle=['#ffd0d6','#ff3a50','#ff0a2a','#ff8a9a'][i%4];cx.beginPath();cx.arc(x+Math.sin(i*5.1+t*1.5)*36,y-14-ph*150,1.6+(i%3)*.6,0,7);cx.fill()}
 cx.restore()}
/* героиня с красным светящимся контуром: силуэт красится в красный и рисуется вокруг неё несколько раз */
const AO=document.createElement('canvas'),AX=AO.getContext('2d');
function auraMouse(p,t){
 const M=cx.getTransform(),x0=Math.floor(M.a*(p.x-80)+M.e),y0=Math.floor(M.d*(GY+p.y-150)+M.f),w=Math.ceil(M.a*160),h=Math.ceil(M.d*165);
 if(AO.width!==w||AO.height!==h){AO.width=w;AO.height=h}
 AX.setTransform(1,0,0,1,0,0);AX.clearRect(0,0,w,h);AX.setTransform(M.a,0,0,M.d,M.e-x0,M.f-y0);
 PX=AX;drawMouse(p);PX=null;
 AX.setTransform(1,0,0,1,0,0);AX.globalCompositeOperation='source-in';AX.fillStyle='#ff1838';AX.fillRect(0,0,w,h);AX.globalCompositeOperation='source-over';
 const pu=.75+.25*Math.sin(t*9);cx.save();cx.setTransform(1,0,0,1,0,0);cx.globalCompositeOperation='lighter';
 for(const[r,a]of[[5,.22],[3,.4],[1.6,.55]]){const R=r*S;cx.globalAlpha=a*pu;
  for(let k=0;k<8;k++){const an=k*Math.PI/4;cx.drawImage(AO,x0+Math.cos(an)*R,y0+Math.sin(an)*R)}}
 cx.restore();cx.setTransform(M);drawMouse(p);
 cx.save();cx.setTransform(1,0,0,1,0,0);cx.globalCompositeOperation='lighter';cx.globalAlpha=.2*pu;cx.drawImage(AO,x0,y0);cx.restore();cx.setTransform(M)}
function kryDraw(g){
 const k=g.kry;if(!k)return;let s,fi;
 if(k.a==='appear'){s=KRS.appear;if(g.resq&&g.resq.st<2)return;fi=Math.min(s.m.n-1,Math.floor(k.t*6))}
 else if(k.a==='cast'){s=KRS.cast;fi=Math.min(s.m.n-1,Math.floor(k.t*8))}
 else{s=KRS.idle;fi=Math.floor(g.t*2)%s.m.n}
 if(!s||!s.img.complete||!s.img.naturalWidth)return;const m=s.m,sc=KH*(m.k||1);
 cx.fillStyle='rgba(0,0,0,.35)';cx.beginPath();cx.ellipse(k.x,GY+2,34,6,0,0,7);cx.fill();
 cx.save();cx.translate(k.x,GY+3);cx.scale(k.f*sc,sc);
 cx.drawImage(s.img,(fi%m.cols)*m.cw,Math.floor(fi/m.cols)*m.ch,m.cw,m.ch,-m.ax,-m.ay,m.cw,m.ch);cx.restore()}

function drawBridge(){const im=ARI.bridge;if(!im||!im.complete)return;const x0=W/2-320;for(let k=-2;k<=2;k++)cx.drawImage(im,x0+k*640,282.5,640,125)}
function dAmb(t){
 cx.save();cx.globalCompositeOperation='lighter';const x=W/2-480,w=960,h=360;
 for(let i=0;i<34;i++){const sp=.05+.09*hs1(i),ph=(t*sp+hs1(i+7))%1,py=h*(1.05-ph*1.15),px=x+w*hs1(i+3)+Math.sin(t*(.7+hs1(i))*2+i)*12,r=.8+1.8*hs1(i+11),al=Math.sin(ph*Math.PI)*(.55+.45*Math.sin(t*6+i));
  if(al<=0)continue;cx.globalAlpha=al*.3;cx.fillStyle='#ff7a2a';cx.beginPath();cx.arc(px,py,r*2.6,0,7);cx.fill();cx.globalAlpha=al;cx.fillStyle=i%3?'#ffb050':'#ffe0a0';cx.beginPath();cx.arc(px,py,r,0,7);cx.fill()}
 cx.restore()}
/* последний удачный кадр дракона: пока видео перематывается или не готово, показываем его — без пропаданий */
const LC=document.createElement('canvas');LC.width=1280;LC.height=490;const LX=LC.getContext('2d');let lastOK=0,lastMir=0;
function dBlit(name,mir,al,cache){const v=DV[name],ok=v&&!v.seeking&&v.readyState>=2&&glVid(v);let src=GLC,m=mir;
 if(cache){if(ok){LX.clearRect(0,0,1280,490);LX.drawImage(GLC,0,0);lastOK=1;lastMir=mir}if(!lastOK)return 0;src=LC;m=lastMir}
 else if(!ok)return 0;
 cx.save();cx.globalAlpha=al;cx.translate(DXp(),0);if(m)cx.scale(-1,1);cx.drawImage(src,-DVW/2,0,DVW,DVH);cx.restore();return 1}
function dDraw(g){
 const d=g.dg,t=g.t,im=ARI.cave;
 cx.fillStyle='#0a0503';cx.fillRect(-20,-OY-20,W+40,H+OY+40);
 if(im&&im.complete&&im.naturalWidth)cx.drawImage(im,W/2-480,-180,960,540);
 dAmb(t);
 if(d.a==='death'&&d.fb){const q=Math.min(1,(d.t-d.fbt)/2.2);cx.save();cx.translate(Math.sin(t*40)*6*(1-q),q*q*140);dBlit(d.cur,d.mir,Math.max(0,1-q),1);
  if(q<1){cx.globalCompositeOperation='lighter';cx.globalAlpha=(1-q)*(.25+.2*Math.sin(t*18));dBlit(d.cur,d.mir,(1-q)*.35,1)}cx.restore()}
 else dBlit(d.cur,d.mir,1,1);
 if(d.xf>0&&d.prev)dBlit(d.prev,d.pmir,Math.min(1,d.xf/.14),0);
 drawBridge();
 for(const c of d.cracks){cx.save();cx.globalAlpha=Math.min(1,c.l);
  if(c.fire){cx.globalCompositeOperation='lighter';const gr=cx.createRadialGradient(c.x,GY-6,0,c.x,GY-6,22);gr.addColorStop(0,'rgba(255,200,80,.6)');gr.addColorStop(1,'rgba(255,60,0,0)');cx.fillStyle=gr;cx.fillRect(c.x-22,GY-30,44,40)}
  else{cx.strokeStyle='rgba(20,10,8,.8)';cx.lineWidth=1.6;for(let j=0;j<6;j++){cx.beginPath();cx.moveTo(c.x,GY);let x=c.x,y=GY;for(let s=0;s<4;s++){x+=(hs1(c.seed+j*7+s)-.5)*30+(j<3?-8:8);y+=(hs1(c.seed+j*3+s*5)-.3)*6;cx.lineTo(x,y)}cx.stroke()}}
  cx.restore()}
 const burning=d.a==='breath'&&(d.held&&!d.hdone||d.fs&&d.zone);
 if(d.zone&&!d.zone.done&&!burning){const z=d.zone,pu=.55+.45*Math.sin(z.t*14);cx.save();cx.globalCompositeOperation='lighter';
  const gr=cx.createLinearGradient(0,GY-70,0,GY+8);gr.addColorStop(0,'rgba(255,20,30,0)');gr.addColorStop(1,'rgba(255,30,40,'+(.28*pu)+')');
  cx.fillStyle=gr;cx.fillRect(z.x0,GY-70,z.x1-z.x0,78);cx.fillStyle='rgba(255,60,60,'+(.55*pu)+')';cx.fillRect(z.x0,GY-2,z.x1-z.x0,4);cx.restore()}
 fireDraw(d);pdraw(cx,d.dust);
 if(burning){cx.save();cx.globalCompositeOperation='lighter';cx.fillStyle='rgba(255,110,30,'+(.07+.04*Math.sin(t*25))+')';cx.fillRect(-20,-OY-20,W+40,H+OY+40);cx.restore()}}

function dOverlay(g){ /* поверх героев: молнии, луч, сфера, лечение */
 const r=g.resq,p=g.p,k=g.kry;cx.save();cx.globalCompositeOperation='lighter';cx.lineCap='round';cx.lineJoin='round';
 if(r&&r.lb&&(r.st===1||(r.st===2&&r.t<2.4))){const al=r.st===2&&r.t>1.6?Math.max(0,(2.4-r.t)/.8):1;lbDraw(r.lb,al)}
 if(r&&r.st===2&&r.t<3.2){const k2=r.t<1.6?.7+.3*Math.random():Math.max(0,(3.2-r.t)/1.6),gx=r.kx;
  const gr=cx.createRadialGradient(gx,GY,0,gx,GY,170);gr.addColorStop(0,'rgba(255,90,110,'+(.55*k2)+')');gr.addColorStop(.4,'rgba(255,20,50,'+(.25*k2)+')');gr.addColorStop(1,'rgba(255,0,30,0)');cx.fillStyle=gr;cx.fillRect(gx-170,GY-170,340,250)}
 if(r&&r.fl>0){cx.fillStyle='rgba(255,170,185,'+(.35*r.fl)+')';cx.fillRect(-20,-OY-20,W+40,H+OY+40)}
 if(r&&r.st===1){
  const gr=cx.createRadialGradient(p.x,GY-12,0,p.x,GY-12,40);gr.addColorStop(0,'rgba(255,60,80,.8)');gr.addColorStop(1,'rgba(255,0,30,0)');cx.fillStyle=gr;cx.fillRect(p.x-40,GY-52,80,80)}
 
 if(r&&r.st===3){const q=.6+.4*Math.sin(g.t*12),gr=cx.createRadialGradient(p.x,GY-40,0,p.x,GY-40,90);gr.addColorStop(0,'rgba(255,120,140,'+(.6*q)+')');gr.addColorStop(1,'rgba(255,0,40,0)');cx.fillStyle=gr;cx.fillRect(p.x-90,GY-130,180,180);
  if(k)bolt(k.x+k.f*60,GY-95,p.x,GY-40,2,'#ff6a7a')}
 const tongues=(x,y,r,tt,n)=>{ /* языки красного пламени вокруг сгустка */
  for(let i=0;i<n;i++){const an=tt*2.2+i*6.283/n+Math.sin(tt*5+i)*.4,len=r*(1.15+.55*Math.sin(tt*9+i*1.7)),w=r*.42;
   const tx=x+Math.cos(an)*len,ty=y+Math.sin(an)*len-r*.25,bx=x+Math.cos(an+1.2)*w,by=y+Math.sin(an+1.2)*w,ex=x+Math.cos(an-1.2)*w,ey=y+Math.sin(an-1.2)*w;
   const gr=cx.createLinearGradient(x,y,tx,ty);gr.addColorStop(0,'rgba(255,90,110,.75)');gr.addColorStop(.6,'rgba(220,10,40,.45)');gr.addColorStop(1,'rgba(140,0,30,0)');
   cx.fillStyle=gr;cx.beginPath();cx.moveTo(bx,by);cx.quadraticCurveTo(x+Math.cos(an+.5)*len*.7,y+Math.sin(an+.5)*len*.7-r*.2,tx,ty);cx.quadraticCurveTo(x+Math.cos(an-.5)*len*.7,y+Math.sin(an-.5)*len*.7-r*.2,ex,ey);cx.closePath();cx.fill()}};
 const blob=(x,y,r,tt)=>{tongues(x,y,r*1.15,tt+1.3,7);
  let gr=cx.createRadialGradient(x,y,0,x,y,r*1.9);gr.addColorStop(0,'rgba(255,60,80,.55)');gr.addColorStop(1,'rgba(160,0,30,0)');cx.fillStyle=gr;cx.beginPath();cx.arc(x,y,r*1.9,0,7);cx.fill();
  tongues(x,y,r*.8,-tt*1.4,5);
  gr=cx.createRadialGradient(x,y,0,x,y,r);gr.addColorStop(0,'rgba(255,245,245,1)');gr.addColorStop(.35,'rgba(255,120,140,.95)');gr.addColorStop(.75,'rgba(230,20,50,.6)');gr.addColorStop(1,'rgba(160,0,30,0)');
  cx.fillStyle=gr;cx.beginPath();cx.ellipse(x,y,r*(1+.08*Math.sin(tt*17)),r*(1+.08*Math.cos(tt*13)),tt,0,7);cx.fill()};
 const trail=L=>{if(!L)return;for(const f of L){const a=1-f.l/f.m;cx.globalAlpha=a*.8;const gr=cx.createRadialGradient(f.x,f.y,0,f.x,f.y,f.s);gr.addColorStop(0,['rgba(255,200,210,1)','rgba(255,40,70,1)','rgba(170,0,30,1)'][f.c]);gr.addColorStop(1,'rgba(150,0,30,0)');cx.fillStyle=gr;cx.beginPath();cx.arc(f.x,f.y,f.s,0,7);cx.fill()}cx.globalAlpha=1};
 if(k){trail(k.trail);if(k.orb)trail(k.orb.tr)}
 if(k&&k.a==='cast'&&!k.shot){const q=Math.min(1,k.t/1.4);blob(k.x+k.f*70,GY-95,(k.big?10:6)+(k.big?16:10)*q,g.t)}
 if(k&&k.orb&&k.orb.cx!==undefined){const o=k.orb;blob(o.cx,o.cy,o.big?26:15,g.t)}
 cx.restore();
 if(g.wf2>0){cx.fillStyle='rgba(255,255,255,'+Math.min(1,g.wf2)*.8+')';cx.fillRect(-20,-OY-20,W+40,H+OY+40)}}

