function vbSync(g){const e=g.e,L=BV[g.b.id],v=L&&L[e.vc];if(!v)return;
 if(g.pause){if(!v.paused)v.pause()}else{if(v.paused&&!v.ended)v.play().catch(()=>{});const r=e.vr*(g.sl>0?.3:1);if(v.playbackRate!==r)v.playbackRate=r}}
